CREATE TABLE local_kitchen_assignment_ops(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES local_principals(id), generation TEXT NOT NULL, device TEXT NOT NULL, request TEXT NOT NULL CHECK(length(request)<=4096), state TEXT NOT NULL CHECK(state IN('prepared','unknown','accepted','refused')), result TEXT, acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN(0,1)), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK((state IN('accepted','refused'))=(result IS NOT NULL)), CHECK(acknowledged=0 OR state IN('accepted','refused')));
CREATE UNIQUE INDEX kitchen_one_pending_assignment ON local_kitchen_assignment_ops(actor_id,generation,device) WHERE acknowledged=0 AND device='desktop';
CREATE TRIGGER kitchen_assignment_identity BEFORE UPDATE ON local_kitchen_assignment_ops WHEN NEW.id<>OLD.id OR NEW.actor_id<>OLD.actor_id OR NEW.generation<>OLD.generation OR NEW.device<>OLD.device OR NEW.request<>OLD.request OR NEW.created_at<>OLD.created_at OR (OLD.state IN('accepted','refused') AND (NEW.state<>OLD.state OR NEW.result<>OLD.result)) OR NEW.acknowledged<OLD.acknowledged BEGIN SELECT RAISE(ABORT,'Assignment identity/result is immutable'); END;
CREATE TRIGGER kitchen_assignment_no_delete BEFORE DELETE ON local_kitchen_assignment_ops BEGIN SELECT RAISE(ABORT,'Preserve assignment recovery'); END;
PRAGMA user_version=20;
